def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    import math

    if not isinstance(text, str):
        raise TypeError

    # Strip leading/trailing whitespace
    text = text.strip()

    # Check for empty string
    if not text:
        raise ValueError

    # Check for leading sign
    negative = False
    if text[0] == '-':
        negative = True
        text = text[1:]
    elif text[0] == '+':
        raise ValueError

    if not text:
        raise ValueError

    # Parse components
    total_ms = 0
    units_order = {'w': 6, 'd': 5, 'h': 4, 'm': 3, 's': 2, 'ms': 1}
    last_unit_order = 7

    i = 0
    num_components = 0

    while i < len(text):
        # Skip spaces between components
        while i < len(text) and text[i] == ' ':
            i += 1

        if i >= len(text):
            break

        # Parse number
        j = i
        has_dot = False
        while j < len(text) and (text[j].isdigit() or (text[j] == '.' and not has_dot)):
            if text[j] == '.':
                has_dot = True
            j += 1

        if i == j:
            raise ValueError

        number_str = text[i:j]

        # Validate fraction format (must have digits on both sides of decimal)
        if has_dot:
            parts = number_str.split('.')
            if not parts[0] or not parts[1]:
                raise ValueError

        i = j

        # Check for space before unit (invalid)
        if i < len(text) and text[i] == ' ':
            raise ValueError

        # Parse unit
        if i >= len(text):
            raise ValueError

        if text[i:i+2] == 'ms':
            unit = 'ms'
            i += 2
        elif text[i] in units_order:
            unit = text[i]
            i += 1
        else:
            raise ValueError

        # Validate unit order (strictly descending)
        unit_order = units_order[unit]
        if unit_order >= last_unit_order:
            raise ValueError
        last_unit_order = unit_order

        # Check fraction only on last component
        if has_dot:
            # Look ahead to see if there are more components
            temp_i = i
            while temp_i < len(text) and text[temp_i] == ' ':
                temp_i += 1
            if temp_i < len(text):  # There's more content after this component
                raise ValueError

        num_components += 1

        # Convert to milliseconds
        number = float(number_str)

        unit_to_ms = {
            'w': 7 * 24 * 60 * 60 * 1000,
            'd': 24 * 60 * 60 * 1000,
            'h': 60 * 60 * 1000,
            'm': 60 * 1000,
            's': 1000,
            'ms': 1
        }

        total_ms += number * unit_to_ms[unit]

    if num_components == 0:
        raise ValueError

    # Apply negation
    if negative:
        total_ms = -total_ms

    # Round to nearest millisecond with halves away from zero
    if total_ms >= 0:
        result = math.floor(total_ms + 0.5)
    else:
        result = math.ceil(total_ms - 0.5)

    return int(result)
